$ErrorActionPreference = 'Stop'
$manifest = Get-Content -Raw -LiteralPath third-party/git-tools/manifest.json | ConvertFrom-Json
$scratch = Join-Path $env:RUNNER_TEMP ('gen-installed-inputs-' + [guid]::NewGuid().ToString('N'))
New-Item -ItemType Directory -Path $scratch | Out-Null
foreach ($tool in @(@{name='git'; pin=$manifest.git}, @{name='gh'; pin=$manifest.github})) {
  $pin = $tool.pin
  if ($pin.url -notmatch '^https://github\.com/(git-for-windows/git|cli/cli)/releases/download/[^?#\s]+\.zip$' -or $pin.archiveSha256 -notmatch '^[0-9a-f]{64}$') {
    throw 'Invalid declared Git packaging archive identity'
  }
  $archive = Join-Path $scratch ($tool.name + '.zip')
  Invoke-WebRequest -Uri $pin.url -OutFile $archive -TimeoutSec 180
  if ((Get-FileHash -LiteralPath $archive -Algorithm SHA256).Hash.ToLowerInvariant() -ne $pin.archiveSha256) {
    throw 'Declared Git packaging archive checksum mismatch'
  }
  $expanded = Join-Path $scratch $tool.name
  Expand-Archive -LiteralPath $archive -DestinationPath $expanded
  $source = $expanded
  if ($tool.name -eq 'gh' -and -not (Test-Path -LiteralPath (Join-Path $source 'bin/gh.exe'))) {
    $source = Join-Path $expanded ('gh_' + $pin.version + '_windows_amd64')
  }
  $prefix = '.harness-tool-bundles/' + $tool.name + '/'
  $destination = Join-Path $PWD ('.harness-tool-bundles/' + $tool.name)
  if (Test-Path -LiteralPath $destination) { throw 'Packaging input destination already exists' }
  New-Item -ItemType Directory -Path $destination | Out-Null
  foreach ($file in @($manifest.files | Where-Object { $_.path.StartsWith($prefix) })) {
    $relative = $file.path.Substring($prefix.Length)
    if ([string]::IsNullOrWhiteSpace($relative) -or $relative -match '(^|/)\.\.?(/|$)|[\\:]|^/|//|/$' -or $file.sha256 -notmatch '^[0-9a-f]{64}$') { throw 'Invalid declared Git payload path' }
    $payloadInput = Join-Path $source $relative
    $payloadOutput = Join-Path $destination $relative
    if ((Get-Item -LiteralPath $payloadInput).Length -ne $file.bytes -or (Get-FileHash -LiteralPath $payloadInput -Algorithm SHA256).Hash.ToLowerInvariant() -ne $file.sha256) { throw 'Declared Git payload checksum mismatch' }
    New-Item -ItemType Directory -Path (Split-Path -Parent $payloadOutput) -Force | Out-Null
    Copy-Item -LiteralPath $payloadInput -Destination $payloadOutput
  }
}
node --import tsx --input-type=module -e "import {collectGitTools} from './scripts/git-assets.ts'; const value=await collectGitTools(process.cwd()); console.log(JSON.stringify({files:value.files.length,bytes:value.bytes}));"
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }

observedInputStaging.observedScript:
$ErrorActionPreference = 'Stop'
$lock = Get-Content -Raw -LiteralPath third-party/integrations/PYTHON_LOCK.json | ConvertFrom-Json
$wheels = Join-Path $env:RUNNER_TEMP ('gen-packaging-wheels-' + [guid]::NewGuid().ToString('N'))
New-Item -ItemType Directory -Path $wheels | Out-Null
$names = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
foreach ($distribution in $lock.distributions) {
  if ($distribution.sourceUrl -notmatch '^https://files\.pythonhosted\.org/[^?#\s]+\.whl$' -or $distribution.wheelSha256 -notmatch '^[0-9a-f]{64}$') { throw 'Invalid pinned integration wheel identity' }
  $name = [System.IO.Path]::GetFileName(([System.Uri]$distribution.sourceUrl).AbsolutePath)
  if ($name -notmatch '^[A-Za-z0-9_.+-]+\.whl$' -or -not $names.Add($name)) { throw 'Ambiguous pinned integration wheel filename' }
  $archive = Join-Path $wheels $name
  Invoke-WebRequest -Uri $distribution.sourceUrl -OutFile $archive -TimeoutSec 180
  if ((Get-FileHash -LiteralPath $archive -Algorithm SHA256).Hash.ToLowerInvariant() -ne $distribution.wheelSha256) { throw 'Pinned integration wheel archive checksum mismatch' }
}
"HARNESS_INTEGRATION_WHEELS=$wheels" >> $env:GITHUB_ENV
Write-Output ('HARNESS_PINNED_INTEGRATION_WHEELS=' + (@{count=$names.Count; sourceLockSha256=(Get-FileHash -LiteralPath third-party/integrations/PYTHON_LOCK.json -Algorithm SHA256).Hash.ToLowerInvariant()} | ConvertTo-Json -Compress))
